const fs = require('fs');
const path = require('path');
if (!argumentName) return sendTrackedMessage(sock, remoteJid, 'Usage: !remind <minutes> <message>\nExample: !remind 30 Check the oven');
const match = argumentName.trim().match(/^(\d+)\s+(.+)$/);
if (!match) return sendTrackedMessage(sock, remoteJid, 'Usage: !remind <minutes> <message>');
const minutes = parseInt(match[1]);
const message = match[2];
if (minutes < 1 || minutes > 1440) return sendTrackedMessage(sock, remoteJid, 'Minutes must be 1-1440 (24h max).');
const remindersFile = path.resolve(__rootdir, 'reminders.json');
let reminders = [];
try { reminders = JSON.parse(fs.readFileSync(remindersFile, 'utf-8')); } catch {}
const reminder = {
  id: Date.now().toString(36),
  chatJid: remoteJid,
  message,
  remindAt: Date.now() + minutes * 60 * 1000,
  senderName: msg.pushName || 'You'
};
reminders.push(reminder);
fs.writeFileSync(remindersFile, JSON.stringify(reminders, null, 2));
await sendTrackedMessage(sock, remoteJid, `⏰ Reminder set! I'll remind you in ${minutes} minute(s):\n${message}`);
setTimeout(async () => {
  try {
    await sendTrackedMessage(sock, reminder.chatJid, `⏰ *Reminder for ${reminder.senderName}:*\n${reminder.message}`);
    let current = [];
    try { current = JSON.parse(fs.readFileSync(remindersFile, 'utf-8')); } catch {}
    current = current.filter(r => r.id !== reminder.id);
    fs.writeFileSync(remindersFile, JSON.stringify(current, null, 2));
  } catch (e) {}
}, minutes * 60 * 1000);
